    86→            <-led_to[..3]<-vault_memory AS descendants
    87→        FROM vault_memory
    88→        WHERE embedding <|{top_k}|> {vec}
    89→        FETCH sources, descendants
    90→        ORDER BY score DESC;
    91→    """)
